item.description:
文章語言：台語
        <figure><img src="https://www.kiantiong.com/images/kautian13-cover.png"
    alt="圖片內底的意思你敢攏有捌？"><figcaption>
      <p>圖片內底的意思你敢攏有捌？</p>
    </figcaption>
</figure>

<p>今仔日的教典僻智識內容較實用，共逐家分享教典內底所有的「有 ​ 輕聲意思就無仝的詞」，攏總有八組，是透過表格工具寫一寡函數對教典開放下載的文字資料篩選出來的。
這種例整理起來不止仔趣味，有一寡的意思嘛是我以早分無啥清楚的，分享予逐家，嘛歡迎逐家加補充其他敢閣有啥物類似的例教典無特別收錄的。</p>
<div class="carousel-container">
  <div class="carousel-wrapper">
    <div class="carousel-track">
      <img src="https://www.kiantiong.com/images/kautian13-1.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian13-2.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian13-3.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian13-4.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian13-5.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian13-6.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian13-7.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian13-8.png" class="carousel-img" loading="lazy" />
    </div>
  </div>
  <div class="carousel-controls">
    <button class="carousel-btn prev">&#8592;</button>
    <div class="carousel-indicator">
      <span class="carousel-current">1</span>/<span class="carousel-total"
        >8</span
      >
    </div>
    <button class="carousel-btn next">&#8594;</button>
  </div>
</div>
<script>
  (function () {
    const container = document.currentScript.previousElementSibling;
    const track = container.querySelector(".carousel-track");
    const images = track.querySelectorAll("img");
    const prevBtn = container.querySelector(".carousel-btn.prev");
    const nextBtn = container.querySelector(".carousel-btn.next");
    const indicator = container.querySelector(".carousel-indicator");
    const current = indicator.querySelector(".carousel-current");
    let idx = 0;
    function update() {
      track.style.transform = `translateX(-${idx * 100}%)`;
      current.textContent = idx + 1;
    }
    prevBtn.onclick = function () {
      idx = (idx - 1 + images.length) % images.length;
      update();
    };
    nextBtn.onclick = function () {
      idx = (idx + 1) % images.length;
      update();
    };

    let startX = null;
    track.addEventListener("touchstart", (e) => {
      startX = e.touches[0].clientX;
    });
    track.addEventListener("touchend", (e) => {
      if (startX === null) return;
      let dx = e.changedTouches[0].clientX - startX;
      if (Math.abs(dx) > 50) {
        if (dx < 0) nextBtn.onclick();
        else prevBtn.onclick();
      }
      startX = null;
    });
  })();
</script>
